#include <Stepper.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
Stepper drillStepper(2048, 8, 10, 9, 11);
const int ENCODER_CLK = 2;
const int ENCODER_DT = 3;
volatile int drillDepthMm = 0;

void readEncoder() {
  int dtVal = digitalRead(ENCODER_DT);
  if (dtVal == HIGH) drillDepthMm++;
  else drillDepthMm--;
}

void setup() {
  lcd.init(); lcd.backlight();
  drillStepper.setSpeed(12);
  pinMode(ENCODER_CLK, INPUT_PULLUP);
  pinMode(ENCODER_DT, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(ENCODER_CLK), readEncoder, FALLING);
}

void loop() {
  lcd.setCursor(0, 0);
  lcd.print("DRILL DEPTH:    ");
  lcd.setCursor(0, 1);
  lcd.print(drillDepthMm);
  lcd.print(" mm            ");
  delay(100);
}
